const mongoose = require('mongoose');

const bookingSchema = new mongoose.Schema({
  itemId: {
    type: String,
    required: true
  },
  borrowerId: {
    type: String,
    required: true
  },
  lenderId: {
    type: String,
    required: true
  },
  startDate: {
    type: Date,
    required: true
  },
  endDate: {
    type: Date,
    required: true
  },
  status: {
    type: String,
    enum: ['Pending', 'Confirmed', 'Completed'],
    default: 'Pending'
  }
});

const Booking = mongoose.model('Booking', bookingSchema);

module.exports = Booking;

const express = require('express');
const router = express.Router();
const Booking = require('../models/Booking');

// Request a booking for an item
router.post('/api/bookings', async (req, res) => {
  try {
    const { itemId, borrowerId, lenderId, startDate, endDate } = req.body;
    if (!itemId || !borrowerId || !lenderId || !startDate || !endDate) {
      return res.status(400).json({ message: 'All fields are required' });
    }

    const booking = new Booking({
      itemId,
      borrowerId,
      lenderId,
      startDate,
      endDate,
      status: 'Pending'
    });

    await booking.save();
    res.status(201).json({ message: 'Booking request created', booking });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

// Confirm a booking request
router.put('/api/bookings/:id/confirm', async (req, res) => {
  try {
    const { id } = req.params;
    const booking = await Booking.findById(id);
    if (!booking) {
      return res.status(404).json({ message: 'Booking not found' });
    }

    booking.status = 'Confirmed';
    await booking.save();
    res.json({ message: 'Booking confirmed', booking });
  } catch (error) {
    res.status(500).json({ message: error.message });
  }
});

module.exports = router;

const express = require('express');
const cors = require('cors');
const mongoose = require('mongoose');
const bookingRoutes = require('./controllers/bookingController');

const app = express();
app.use(cors());
app.use(express.json());

// Connect to MongoDB
mongoose.connect(process.env.MONGO_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
}).then(() => {
  console.log('Connected to MongoDB');
}).catch((error) => {
  console.error('Failed to connect to MongoDB', error);
});

// Define routes
app.use('/api/bookings', bookingRoutes);

const PORT = process.env.PORT || 5003;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
